// Each kit's rules (rules/<kit>/conventions.md and lessons.md, as absolute
// paths, so whoever reads them finds them wherever the core is installed),
// and the libraries a kit names for each job: the table under "## The
// libraries" in its conventions, which a product's blueprint extends with
// its own "## Libraries" table. A package is named in backticks in a
// table's Library column; `@scope/*` and `name-*` stand for every package
// that matches. A product whose `dependencies` hold a package neither table
// names fails the factory's checks: a job the kit lacks gets its row, not
// home-made code or an unnoticed package.
import { existsSync, readFileSync } from "node:fs";
import { join } from "node:path";
const RULES = join(import.meta.dirname, "..", "rules");
const HEADINGS = new Set(["## The libraries", "## Libraries"]);
const PACKAGE = /^(@[a-z0-9][\w.~-]*\/)?[a-z0-9*][\w.~*-]*$/;
export function rulesOf(kit) {
    return [join(RULES, kit, "conventions.md"), join(RULES, kit, "lessons.md")];
}
// The package names, and patterns, a Markdown text's libraries table names.
export function librariesIn(markdown) {
    const names = [];
    for (const row of tableRows(markdown)) {
        const library = row.split("|")[2] ?? "";
        for (const [, name] of library.matchAll(/`([^`]+)`/g))
            if (name && PACKAGE.test(name))
                names.push(name);
    }
    return names;
}
// The packages none of the names covers, in the order given.
export function unlisted(packages, names) {
    return [...packages].filter((name) => !names.some((one) => covers(one, name)));
}
// What a product's package.json depends on at run time that neither its
// kit's rules nor its own blueprint name; [] when the kit names no
// libraries (other code) or the product has no package.json.
export function unlistedPackagesOf(folder, rules) {
    const names = [...rules, join(folder, "BLUEPRINT.md")]
        .filter((file) => existsSync(file))
        .flatMap((file) => librariesIn(readFileSync(file, "utf8")));
    if (names.length === 0)
        return [];
    return unlisted(dependenciesOf(folder), names);
}
function dependenciesOf(folder) {
    try {
        const file = JSON.parse(readFileSync(join(folder, "package.json"), "utf8"));
        return Object.keys(file.dependencies ?? {});
    }
    catch {
        return [];
    }
}
function covers(pattern, name) {
    if (!pattern.includes("*"))
        return pattern === name;
    const [before = "", after = ""] = pattern.split("*");
    return name.startsWith(before) && name.endsWith(after);
}
// The rows of the first table after a libraries heading, without its header
// and its separator.
function tableRows(markdown) {
    const lines = markdown.split("\n");
    const start = lines.findIndex((line) => HEADINGS.has(line.trim()));
    if (start === -1)
        return [];
    const rows = [];
    for (const line of lines.slice(start + 1)) {
        if (line.startsWith("## "))
            break;
        if (line.startsWith("|"))
            rows.push(line);
        else if (rows.length > 0)
            break;
    }
    return rows.slice(2);
}
